# GUI environment variables that must survive the switch to root.
_PASSTHROUGH = (
    "DISPLAY", "WAYLAND_DISPLAY", "XAUTHORITY", "XDG_RUNTIME_DIR",
    "XDG_SESSION_TYPE", "XDG_CURRENT_DESKTOP", "XDG_SESSION_DESKTOP",
    "DBUS_SESSION_BUS_ADDRESS", "GDK_BACKEND", "LANG", "LANGUAGE",
    "LC_ALL", "LC_CTYPE", "NO_AT_BRIDGE", "TERM", "COLORTERM",
    "SUDO_USER", "PKEXEC_UID",
)


def is_root():
    return os.geteuid() == 0


def ensure_root():
    """Re-exec this script as root the moment it starts (pkexec -> sudo)."""
    if os.name != "posix" or is_root():
        return
    if os.environ.get("KALI_UNI_ELEV") == "1":        # elevation loop guard
        return
    exe = sys.executable or "/usr/bin/python3"
    script = os.path.abspath(__file__)
    env = {k: os.environ[k] for k in _PASSTHROUGH if os.environ.get(k)}
    env["KALI_UNI_ELEV"] = "1"
    pairs = [f"{k}={v}" for k, v in env.items() if v]

    for argv in (
        ["pkexec", "env", *pairs, exe, script],
        ["sudo", "-E", "--", exe, script],
    ):
        try:
            os.execvpe(argv[0], argv, env)
        except (FileNotFoundError, OSError):
            continue
    # If we reach here no elevator worked — continue without root; the GUI
    # will show a NO ROOT badge and apt errors will appear in the log.
    print("[Kali Uninstaller] WARNING: root elevation failed, "
          "chaltay waqt permission errors aa sakte hain.", file=sys.stderr)


def _real_home():
    """Asli desktop user ka home (sudo/pkexec ke through bhi)."""
    import pwd
    su = os.environ.get("SUDO_USER", "")
    if su:
        try:
            return pwd.getpwnam(su).pw_dir
        except Exception:
            pass
    uid = os.environ.get("PKEXEC_UID", "")
    if uid.isdigit():
        try:
            return pwd.getpwuid(int(uid)).pw_dir
        except Exception:
            pass
    return os.path.expanduser("~")


