    """--doctor: har cheez check karke exact fix command print karo."""
    print("== KALI UNINSTALLER -- DOCTOR ==")
    ok = True
    print(f"[OK] Python {sys.version.split()[0]}")
    try:
        import tkinter                                   # noqa: F401
        print("[OK] tkinter (GUI library)")
    except Exception as exc:
        print(f"[X] tkinter missing ({exc})")
        print("    FIX: sudo apt update && sudo apt install -y python3-tk")
        ok = False
    disp = os.environ.get("DISPLAY", "") or os.environ.get("WAYLAND_DISPLAY", "")
    if disp:
        print(f"[OK] GUI display: {disp}")
    else:
        print("[!] GUI display nahi mila — headless doctor check theek hai; GUI desktop session me kholo")
    if os.geteuid() == 0:
        print("[OK] ROOT mode me chal raha hai")
    else:
        print("[!] ROOT nahi (normal) — launch par password prompt aayega")
    for name in ("dpkg", "dpkg-query", "apt-get"):
        found = shutil.which(name)
        if found:
            print(f"[OK] {name}")
        else:
            print(f"[X] {name} missing!")
            ok = False
    for name in ("pkexec", "sudo"):
        if shutil.which(name):
            print(f"[OK] {name}")
        else:
            print(f"[!] {name} not installed (optional if the other privilege tool is available)")
    for name, why in (("rsvg-convert", "SVG icon conversion"),
                      ("convert", "SVG icon conversion (ImageMagick)"),
                      ("inkscape", "SVG icon conversion")):
        if shutil.which(name):
            print(f"[OK] {name} — {why}")
            break
    else:
        print("[i] SVG converter nahi mila (optional) — SVG-only icons pe "
              "fallback glyph dikhega. FIX: sudo apt install -y librsvg2-bin")
    import glob as _glob
    n_icons = len(_glob.glob("/usr/share/icons/*/64x64/apps/*.png")) + \
        len(_glob.glob("/usr/share/pixmaps/*.png"))
    n_desk = len(_glob.glob("/usr/share/applications/*.desktop")) + \
        len(_glob.glob("/usr/local/share/applications/*.desktop"))
    print(f"[i] Icon sources: {n_desk} desktop files, "
          f"{n_icons} system app icons (tool icons yahin se aate hain)")
    if not is_root() and not (shutil.which("pkexec") or shutil.which("sudo")):
        print("[X] pkexec aur sudo dono missing — privilege elevation mumkin nahi")
        ok = False
    if ok:
        print("== RESULT: READY — 'kali-uninstaller' chalao ==")
    else:
        print("== RESULT: UPAR WALI PROBLEMS FIX KARO ==")
    return ok


