def is_critical(name):
    # Multi-Arch package names may include a suffix such as :amd64.
    base_name = name.split(":", 1)[0]
    return base_name in CRITICAL_EXACT or base_name.startswith(CRITICAL_PREFIX)


class Pkg:
    __slots__ = ("name", "version", "kb", "section", "summary")

    def __init__(self, name, version, kb, section="", summary=""):
        self.name = name
        self.version = version
        self.kb = kb
        self.section = section
        self.summary = summary


class Item:
    """Unified list row: apt package, desktop app, flatpak, snap ya custom tool.

    kind     : "apt" (dpkg package) ya "app" (.desktop application entry /
               koi bhi user-facing TOOL — pip/npm/gem/custom bhi "app" hai)
    strategy : "apt"     -> apt-get remove --purge <name/owner>
               "files"   -> GitHub/custom tool: .desktop + program files delete
               "flatpak" -> flatpak uninstall
               "snap"    -> snap remove
               "pipx"    -> pipx uninstall <name>
               "pip"     -> python3 -m pip uninstall -y <name>
               "npm"     -> npm rm -g <name>
               "gem"     -> gem uninstall -a -x -I <name>
    paths    : files-strategy ke liye extra delete targets (/opt dir, cargo
               bin, AppImage file, git clone folder ...)
    """
    __slots__ = ("iid", "kind", "strategy", "display", "name", "version", "kb",
                 "section", "summary", "owner", "icon_key", "desktop_path",
                 "exec_path", "paths")

    def __init__(self, iid, kind, strategy, display, name, version="", kb=0,
                 section="", summary="", owner=None, icon_key=None,
                 desktop_path=None, exec_path=None, paths=None):
        self.iid = iid
        self.kind = kind
        self.strategy = strategy
        self.display = display
        self.name = name
        self.version = version
        self.kb = kb
        self.section = section
        self.summary = summary
        self.owner = owner
        self.icon_key = icon_key
        self.desktop_path = desktop_path
        self.exec_path = exec_path
        self.paths = list(paths) if paths else []


def type_label(it):
    labels = {"flatpak": "FLATPAK", "snap": "SNAP",
              "pipx": "PIPX", "pip": "PYTHON", "npm": "NODE",
              "gem": "RUBY GEM"}
    if it.strategy in labels:
        return labels[it.strategy]
    if it.strategy == "files":
        return "GITHUB/CUSTOM"
    return "APP" if it.kind == "app" else "APT"


def fmt_size(kb):
    try:
        kb = int(kb)
    except (TypeError, ValueError):
        return "?"
    if kb >= 1024 * 1024:
        return f"{kb / 1048576:.2f} GB"
    if kb >= 1024:
        return f"{kb / 1024:.1f} MB"
    return f"{kb} KB"


def dpkg_packages():
    """Load every installed package with ONE fast dpkg-query call."""
    fmt6 = ("${Package}\t${Version}\t${Installed-Size}\t${Status}"
            "\t${Section}\t${binary:Summary}\n")
    fmt4 = "${Package}\t${Version}\t${Installed-Size}\t${Status}\n"
    proc = None
    for fmt in (fmt6, fmt4):
        try:
            proc = subprocess.run(
                ["dpkg-query", "-W", "-f", fmt],
                capture_output=True, text=True, timeout=90,
            )
        except Exception:
            raise
        if proc.returncode == 0:
            wide = fmt is fmt6
            break
        wide = False
    else:
        raise RuntimeError((proc.stderr if proc else "").strip()
                           or "dpkg-query failed")
    pkgs = []
    for line in proc.stdout.splitlines():
        parts = line.split("\t")
        if wide and len(parts) >= 6:
            name, ver, size, status = parts[0], parts[1], parts[2], parts[3]
            section = parts[4].rsplit("/", 1)[-1].strip()
            summary = " ".join(parts[5:]).replace("\t", " ").strip()
        elif len(parts) >= 4:
            name, ver, size, status = parts[0], parts[1], parts[2], parts[3]
            section = summary = ""
        else:
            continue
        if not status.endswith("installed"):        # installed only
            continue
        pkgs.append(Pkg(name, ver, size, section, summary))
    return pkgs


