def parse_desktop(fp):
    """Ek .desktop file parse karo. Valid Application entry -> dict, warna None.

    NoDisplay / Hidden / invalid TryExec wali entries filter ho jati hain —
    yehi filtering Kali ka application menu bhi karta hai.
    """
    ent = {}
    try:
        with open(fp, "r", encoding="utf-8", errors="ignore") as fh:
            in_entry = False
            for line in fh:
                line = line.strip()
                if line.startswith("["):
                    in_entry = line.lower() == "[desktop entry]"
                    continue
                if not in_entry or "=" not in line:
                    continue
                k, _, v = line.partition("=")
                k = k.strip().lower()
                v = v.strip()
                if k in ("type", "name", "genericname", "comment", "exec",
                         "tryexec", "icon", "nodisplay", "hidden") \
                        and k not in ent:
                    ent[k] = v
    except OSError:
        return None
    if ent.get("type", "").lower() != "application":
        return None
    if ent.get("nodisplay", "").lower() == "true":
        return None
    if ent.get("hidden", "").lower() == "true":
        return None
    if not ent.get("name"):
        return None
    try_exec = ent.get("tryexec", "").strip()
    if try_exec:
        if try_exec.startswith("/"):
            if not os.path.isfile(try_exec):
                return None
        elif shutil.which(try_exec) is None:
            return None
    return ent


def _bulk_owners(paths):
    """Ek dafa dpkg-query -S chala kar path -> owning-package map banao."""
    out = {}
    paths = [p for p in paths if p]
    if not paths or shutil.which("dpkg-query") is None:
        return out
    CH = 150
    for i in range(0, len(paths), CH):
        chunk = paths[i:i + CH]
        try:
            proc = subprocess.run(["dpkg-query", "-S", *chunk],
                                  capture_output=True, text=True, timeout=25)
        except Exception:
            continue
        for line in proc.stdout.splitlines():
            if not line or ":" not in line or "diversion" in line:
                continue
            left, right = line.split(":", 1)
            right = right.strip()
            pkgs = [x.strip() for x in left.split(",") if x.strip()]
            if pkgs and right:
                out.setdefault(right, pkgs[0])
    return out


def _owner_of_path(path):
    """Single path ka owner (fallback — bulk query ke baad bhi na mile to)."""
    if not path or shutil.which("dpkg-query") is None:
        return None
    try:
        proc = subprocess.run(["dpkg-query", "-S", path],
                              capture_output=True, text=True, timeout=5)
        out = proc.stdout
    except Exception:
        return None
    for line in out.splitlines():
        if not line or ":" not in line or "diversion" in line:
            continue
        left = line.split(":", 1)[0]
        pkgs = [x.strip() for x in left.split(",") if x.strip()]
        if pkgs:
            return pkgs[0]
    return None


def _flatpak_apps():
    """app_id -> (display name, version). flatpak na ho to khali dict."""
    apps = {}
    if shutil.which("flatpak") is None:
        return apps
    try:
        proc = subprocess.run(
            ["flatpak", "list", "--app",
             "--columns=application,name,version"],
            capture_output=True, text=True, timeout=8)
        for line in proc.stdout.splitlines():
            parts = [x.strip() for x in line.split("\t")]
            if parts and parts[0]:
                disp = parts[1] if len(parts) > 1 and parts[1] else parts[0]
                ver = parts[2] if len(parts) > 2 else ""
                apps[parts[0]] = (disp, ver)
    except Exception:
        pass
    return apps


def _snap_apps():
    """Installed snap names ka set (snap na ho to khali)."""
    names = set()
    if shutil.which("snap") is None:
        return names
    try:
        proc = subprocess.run(["snap", "list"],
                              capture_output=True, text=True, timeout=8)
        for i, line in enumerate(proc.stdout.splitlines()):
            if i == 0 or not line.strip():
                continue
            names.add(line.split()[0])
    except Exception:
        pass
    return names


def _resolve_exec(exec_value):
    """Exec= ka pehla token -> poori binary path (ya None)."""
    if not exec_value:
        return None
    tok = exec_value.split()[0].strip('"').strip("'")
    if not tok or tok.startswith("%"):
        return None
    if tok.startswith("/"):
        return tok if os.path.exists(tok) else None
    return shutil.which(tok)


