def _run_cmd(cmd, timeout=12):
    """Helper: command chalao -> stdout (ya empty). Kabhi raise nahi karta."""
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True,
                              timeout=timeout)
        return proc.stdout or ""
    except Exception:
        return ""


def _pipx_apps():
    """pipx se install kiye gaye apps: {name: version}."""
    apps = {}
    if shutil.which("pipx") is None:
        return apps
    out = _run_cmd(["pipx", "list", "--short"], timeout=20)
    for line in out.splitlines():
        parts = line.split()
        if parts and parts[0] not in _PKG_INFRA_SKIP:
            apps[parts[0]] = parts[1] if len(parts) > 1 else ""
    if not apps:
        # fallback: venv dirs (pipx --short fail ho to bhi tools dikhein)
        venvs = os.path.join(_real_home(), ".local/share/pipx/venvs")
        try:
            for d in sorted(os.listdir(venvs)):
                if not d.startswith(".") and os.path.isdir(
                        os.path.join(venvs, d)):
                    apps.setdefault(d, "")
        except OSError:
            pass
    return apps


def _pip_console_tools():
    """pip se install hui TOOL packages (jo console script deti hain).

    Sirf console_scripts wale dists list hote hain — libraries nahi (warna
    hazaron python libs list ho jati jo kabhi uninstall nahi karni chahiye).
    Root run par root/system scope + real-user scope dono check hote hain.
    Returns {name: (version, [scripts])}
    """
    tools = {}
    if shutil.which("python3") is None and not os.path.exists(sys.executable):
        return tools
    probes = [(sys.executable, None)]          # app ka apna interpreter
    real = _real_home()
    py3 = shutil.which("python3")
    if py3 and os.path.realpath(py3) != os.path.realpath(sys.executable):
        probes.append((py3, None))
    if is_root() and os.path.isdir(real):
        # real user ke HOME ke saath -> uski ~/.local/lib tools bhi
        probes.append((sys.executable,
                       dict(os.environ, HOME=real,
                            PYTHONNOUSERSITE="0")))
    seen_envs = set()
    for exe, env in probes:
        key = (os.path.realpath(exe), env.get("HOME") if env else None)
        if key in seen_envs:
            continue
        seen_envs.add(key)
        try:
            proc = subprocess.run([exe, "-c", _PIP_PROBE],
                                  capture_output=True, text=True,
                                  timeout=30, env=env)
        except Exception:
            continue
        if proc.returncode != 0:
            continue
        import json as _json
        try:
            data = _json.loads(proc.stdout.strip() or "[]")
        except Exception:
            continue
        for name, ver, scripts in data:
            if not name or name.lower() in _PKG_INFRA_SKIP:
                continue
            if name in tools:
                continue
            tools[name] = (ver, scripts or [])
    return tools


def _npm_globals():
    """npm -g packages: {name: version} (npm/corepack khud skip).

    Scoped packages (@scope/pkg) bhi handle hote hain — uninstall ke
    waqt bhi poora scoped name use hota hai.
    """
    pkgs = {}
    if shutil.which("npm") is None:
        return pkgs
    out = _run_cmd(["npm", "ls", "-g", "--depth=0", "--parseable"],
                   timeout=20)
    lines = [ln for ln in out.splitlines() if ln.strip()]
    for line in lines[1:]:                     # pehli line = global root
        line = line.rstrip("/")
        name = os.path.basename(line)
        parent = os.path.basename(os.path.dirname(line))
        if parent.startswith("@"):
            name = parent + "/" + name         # @scope/pkg
        if not name:
            continue
        base = name.split("/")[-1]
        if base in _PKG_INFRA_SKIP:
            continue
        if name and name not in pkgs:
            pkgs[name] = ""
    return pkgs


def _gem_list():
    """ruby gems (default/stdlib gems skip): {name: version}."""
    gems = {}
    if shutil.which("gem") is None:
        return gems
    out = _run_cmd(["gem", "list", "--local"], timeout=20)
    for line in out.splitlines():
        m = re.match(r"^([A-Za-z0-9_.\-]+)\s+\((.*)\)\s*$", line.strip())
        if not m:
            continue
        name, vers = m.group(1), m.group(2)
        if name.lower() in _PKG_INFRA_SKIP:
            continue
        # "(default: 3.2.8)" -> stdlib default gem, skip
        plain = [v.strip() for v in vers.split(",")
                 if v.strip() and not v.strip().startswith("default")]
        if not plain:
            continue
        gems[name] = plain[0]
    return gems


def _cargo_go_bins(probe_paths):
    """~/.cargo/bin + ~/go/bin ke user tools (rustup/cargo khud skip)."""
    found = []                                 # (name, [paths])
    home = _real_home()
    skips = {"cargo", "rustc", "rustdoc", "rustup", "rust-gdb",
             "rust-gdbgui", "rust-lldb", "rust-lldb", "cargo-clippy",
             "cargo-fmt", "clippy-driver", "cargo-miri", "rls",
             "rust-analyzer", "go", "gofmt"}
    for sub in (("~/.cargo/bin", "cargo"), ("~/go/bin", "go")):
        d = sub[0].replace("~", home, 1)
        kind = sub[1]
        try:
            names = sorted(os.listdir(d))
        except OSError:
            continue
        for fn in names:
            if fn.startswith(".") or fn in skips \
                    or fn in _CORE_TOOLCHAIN_NAMES:
                continue
            fp = os.path.join(d, fn)
            if not os.path.isfile(fp) or os.path.islink(fp) \
                    and not os.path.exists(fp):
                continue
            if not os.access(fp, os.X_OK):
                continue
            found.append((fn, [fp], kind))
    return found


def _opt_programs(probe_paths):
    """/opt ke standalone programs (dpkg-owned skip)."""
    out = []
    try:
        tops = sorted(os.listdir("/opt"))
    except OSError:
        return out
    for d in tops:
        if d.startswith(".") or d in ("kali-uninstaller",):
            continue
        fp = os.path.join("/opt", d)
        if not os.path.isdir(fp):
            continue
        probe_paths.append(fp)                 # dpkg check baad me bulk me
        out.append((d, [fp], "opt"))
    return out


def _custom_binaries(probe_paths):
    """/usr/local/*bin + ~/.local/bin + ~/bin ke standalone executables."""
    found = []
    home = _real_home()
    dirs = ["/usr/local/bin", "/usr/local/sbin",
            os.path.join(home, ".local/bin"), os.path.join(home, "bin")]
    for d in dirs:
        try:
            names = sorted(os.listdir(d))
        except OSError:
            continue
        for fn in names:
            if fn.startswith(".") or fn in _CORE_TOOLCHAIN_NAMES \
                    or fn in _PKG_INFRA_SKIP:
                continue
            fp = os.path.join(d, fn)
            if not os.path.isfile(fp):
                continue
            if not os.access(fp, os.X_OK):
                continue
            if os.path.islink(fp):
                # broken link -> candidate (orphan), real link -> baad me
                # dpkg check hoga
                if not os.path.exists(fp):
                    found.append((fn, [fp], "custom-bin"))
                    continue
            probe_paths.append(fp)
            found.append((fn, [fp], "custom-bin"))
    return found


def _appimages():
    """Home ke aam folders me .AppImage files."""
    found = []
    home = _real_home()
    search = [os.path.join(home, "Applications"),
              os.path.join(home, "AppImages"),
              os.path.join(home, "apps"),
              os.path.join(home, "Downloads"),
              home]
    seen = set()
    for d in search:
        try:
            names = sorted(os.listdir(d))
        except OSError:
            continue
        for fn in names:
            if not fn.lower().endswith(".appimage"):
                continue
            fp = os.path.join(d, fn)
            if fp in seen or not os.path.isfile(fp):
                continue
            seen.add(fp)
            disp = fn[:-len(".AppImage")] if fn.endswith(".AppImage") \
                else fn[:-len(".appimage")]
            found.append((disp, [fp], "appimage"))
    return found


_GIT_PARENTS = ("tools", "Tools", "tool", "Toolz", "toolz", "git", "Git",
                "github", "GitHub", "Github", "repos", "Repos",
                "projects", "Projects", "scripts", "Scripts",
                "Documents/tools", "Documents/Tools", "Desktop")


def _git_tools(taken):
    """GitHub clone folders: ~/tools/<dir> jisme .git/install.sh/Makefile."""
    found = []
    home = _real_home()
    seen = set()
    for parent in _GIT_PARENTS:
        pd = os.path.join(home, parent)
        try:
            subs = sorted(os.listdir(pd))
        except OSError:
            continue
        for s in subs:
            if s.startswith(".") or s in taken or s in seen:
                continue
            fp = os.path.join(pd, s)
            if not os.path.isdir(fp) or os.path.islink(fp):
                continue
            marker = any(os.path.exists(os.path.join(fp, m)) for m in
                         (".git", "install.sh", "Makefile", "makefile",
                          "setup.py", "requirements.txt", "go.mod",
                          "package.json", "Cargo.toml", "pom.xml"))
            if not marker:
                continue
            seen.add(s)
            found.append((s, [fp], "github-clone"))
    return found


def _extra_add_factory(taken_names, taken_execs, lock=None):
    """add() closure — dedup ke saath Item banao (thread-safe optional).

    Parallel sources ek hi taken_names share karte hain — lock zaroori.
    Returns Item ya None (duplicate ho to).
    """
    def norm(s):
        return (s or "").strip().lower()

    def add(iid, strategy, display, name, section, summary, paths=None,
            version="", kb=0, scripts=None):
        key = norm(name)
        if lock:
            lock.acquire()
        try:
            if key in taken_names:
                return None
            taken_names.add(key)
            it = Item(
                iid=iid, kind="app", strategy=strategy, display=display,
                name=name, version=version, kb=kb, section=section,
                summary=summary, icon_key=None,
                exec_path=(paths[0] if paths else None),
                paths=paths, owner=None)
            for p in (paths or []):
                taken_execs.add(p)
            return it
        finally:
            if lock:
                lock.release()
    return add


def _files_bins_job(add, taken_names):
    """cargo/go bins + /opt + custom bins + AppImages + GitHub clones.

    Sab filesystem-scan sources — ek group (ek bulk dpkg filter share
    karte hain). Koi subprocess hang yahan mumkin nahi (sirf os.walk/glob).
    """
    items = []
    probe = []
    for name, paths, kind in _cargo_go_bins(probe):
        it = add("bin::" + name, "files", name, name, kind,
                 ("cargo-installed binary (~/.cargo/bin)" if kind == "cargo"
                  else "go-installed binary (~/go/bin)"),
                 paths=paths, version="custom")
        if it:
            items.append(it)
    for name, paths, kind in _opt_programs(probe):
        it = add("opt::" + name, "files", name, name, kind,
                 "standalone program in /opt (custom install)",
                 paths=paths, version="custom")
        if it:
            items.append(it)
    for name, paths, kind in _custom_binaries(probe):
        it = add("bin::" + name, "files", name, name, kind,
                 "standalone executable (custom install)", paths=paths,
                 version="custom")
        if it:
            items.append(it)
    # bulk dpkg-owned filter (sirf files-strategy rows par lagta hai)
    probe = [p for p in probe if p]
    owned = _bulk_owners(probe) if probe else {}
    if owned:
        real_owned = {os.path.realpath(p) for p in owned}
        keep = []
        for it in items:
            if it.strategy != "files":
                keep.append(it)
                continue
            paths = [p for p in (it.paths or [])
                     if p not in owned
                     and os.path.realpath(p) not in real_owned]
            if not paths:
                continue                    # sab dpkg-owned -> list hi na ho
            it.paths = paths
            it.exec_path = paths[0]
            keep.append(it)
        items = keep
    for name, paths, kind in _appimages():
        it = add("appimage::" + (paths[0] or "").strip().lower(), "files",
                 name, name, kind, "AppImage application",
                 paths=paths, version="appimage")
        if it:
            items.append(it)
    snap = set(taken_names)                 # thread-safe snapshot
    for name, paths, kind in _git_tools(snap):
        it = add("git::" + name, "files", name, name, kind,
                 f"GitHub clone folder ({kind} — folder + files delete honge)",
                 paths=paths, version="clone")
        if it:
            items.append(it)
    return items


def extra_source_jobs(pkg_map, taken_names, taken_execs, lock):
    """(label, fn) list — fn() -> [Item]. HAR source ka apna job (parallel
    chal sakta hai). Koi bhi fn subprocess timeout ke ilawa kuch hang
    nahi kar sakta."""
    add = _extra_add_factory(taken_names, taken_execs, lock)

    def j_pipx():
        items = []
        for name, ver in _pipx_apps().items():
            it = add("pipx::" + name, "pipx", name, name, "pipx",
                     "pipx application (isolated Python CLI tool)",
                     version=ver)
            if it:
                items.append(it)
        return items

    def j_pip():
        items = []
        for name, (ver, scripts) in _pip_console_tools().items():
            s = ("console: " + ", ".join(scripts)) if scripts \
                else "python tool"
            it = add("pip::" + name, "pip", name, name, "pip",
                     f"pip package ({s})", version=ver)
            if it:
                items.append(it)
        return items

    def j_npm():
        items = []
        for name in _npm_globals():
            it = add("npm::" + name, "npm", name, name, "npm",
                     "global npm package (node_modules)", version="")
            if it:
                items.append(it)
        return items

    def j_gem():
        items = []
        for name, ver in _gem_list().items():
            it = add("gem::" + name, "gem", name, name, "gem",
                     "ruby gem", version=ver)
            if it:
                items.append(it)
        return items

    def j_files():
        return _files_bins_job(add, taken_names)

    return [("pipx", j_pipx), ("pip", j_pip), ("npm", j_npm),
            ("gem", j_gem), ("files-bins", j_files)]


def build_extra_stream(pkg_map, taken_names, taken_execs, emit,
                       deadline=60.0, on_skip=None, nthreads=5):
    """EXTRA sources PARALLEL chalao — jaise hi koi source complete ho,
    uske items emit(label, items) se stream hote hain (worker thread se
    GUI queue par).

    GUARANTEED finalize: har source apne daemon watchdog thread me chalta
    hai — budget (deadline) ke andar khatam na ho to SKIP report hota hai
    aur stream aage barh jata hai. Zahen me: source thread daemon hai, wo
    process ke saath hi khatam hota hai — stream KABHI block nahi hota.
    Kabhi raise nahi karta."""
    lock = threading.Lock()
    jobs = extra_source_jobs(pkg_map, taken_names, taken_execs, lock)
    dl = time.monotonic() + max(5.0, deadline)

    def run(label, fn):
        rem = dl - time.monotonic()
        if rem <= 0.2:
            return (label, None, "load budget khatam (60s)")
        box = {}

        def _safe():
            try:
                box["res"] = (label, fn(), None)
            except Exception as exc:
                box["res"] = (label, None, f"error: {exc}")

        th = threading.Thread(target=_safe, daemon=True)
        th.start()
        th.join(rem + 2.0)                 # hard wall: budget + 2s margin
        if th.is_alive():
            return (label, None,
                    f"budget paar ({int(rem)}s) — skip (background me "
                    "chalta rahega, agli refresh me aa jayega)")
        return box.get("res", (label, None, "no result"))

    with ThreadPoolExecutor(max_workers=max(2, nthreads)) as ex:
        fut_map = {ex.submit(run, lbl, fn): lbl for lbl, fn in jobs}
        for fut in as_completed(fut_map):
            lbl = fut_map[fut]
            try:
                label, items, err = fut.result()
            except Exception as exc:               # defensive — kabhi nahi
                label, items, err = lbl, None, str(exc)
            if err:
                if on_skip:
                    try:
                        on_skip(label, err)
                    except Exception:
                        pass
            elif items:
                try:
                    emit(label, items)
                except Exception:
                    pass


def build_extra_items(pkg_map, taken_names, taken_execs, owners_probe):
    """COMPAT (sync) — purana API: sab extra sources ek saath, return list."""
    extra = []
    jobs = extra_source_jobs(pkg_map, taken_names, taken_execs, None)
    for _label, fn in jobs:
        try:
            got = fn()
        except Exception:
            continue
        if got:
            extra.extend(got)
    return extra


def build_core_items(pkg_map, flat_apps=None, snap_names=None):
    """FAST CORE: .desktop apps (dpkg/flatpak/snap/custom) + saare apt
    packages. Ye chunk-1 hai — GUI me sab se pehle paint hoti hai.

    flatpak/snap pre-warmed results worker se aate hain (8s timeout ke
    saath) — wedged snapd ab core load ko 10 minute block nahi kar sakta.
    """
    if flat_apps is None:
        flat_apps = _flatpak_apps()
    if snap_names is None:
        snap_names = _snap_apps()
    items = []

    # ---------- phase 1: sab .desktop entries collect karo (priority order) --
    entries = []                                    # (fp, src_dir, stem, ent)
    seen_stems = set()
    for src_dir in desktop_source_dirs():
        try:
            names = sorted(os.listdir(src_dir))
        except OSError:
            continue
        for fn in names:
            if not fn.endswith(".desktop"):
                continue
            stem = fn[:-len(".desktop")].lower()
            if stem in seen_stems:
                continue
            fp = os.path.join(src_dir, fn)
            ent = parse_desktop(fp)
            if not ent:
                continue
            seen_stems.add(stem)
            entries.append((fp, src_dir, stem, ent))

    # ---------- phase 2: bulk owner detection (ek fast dpkg-query call) ------
    owners = _bulk_owners([fp for fp, _, _, _ in entries])

    # ---------- phase 3: har entry ko Item banao -----------------------------
    per_query = 0
    pq_dl = time.monotonic() + 20.0    # fallback single-queries ka budget
    for fp, src_dir, stem, ent in entries:
        display = ent.get("name", stem)
        comment = ent.get("comment") or ent.get("genericname") or ""
        icon_key = ent.get("icon") or None
        exec_path = _resolve_exec(ent.get("exec"))

        if "flatpak" in src_dir:
            app_id = stem
            disp, ver = flat_apps.get(app_id, (display, ""))
            items.append(Item(
                iid="app::" + stem, kind="app", strategy="flatpak",
                display=disp or display, name=app_id, version=ver,
                section="flatpak",
                summary=comment or "Flatpak application",
                owner=None, icon_key=icon_key, desktop_path=fp,
                exec_path=exec_path))
            continue

        if "snapd" in src_dir and snap_names:
            cand = stem.split("_", 1)[0]
            base = os.path.basename(exec_path) if exec_path else ""
            if cand not in snap_names and base in snap_names:
                cand = base
            if cand in snap_names:
                items.append(Item(
                    iid="app::" + stem, kind="app", strategy="snap",
                    display=display, name=cand, version="",
                    section="snap",
                    summary=comment or "Snap application",
                    owner=None, icon_key=icon_key, desktop_path=fp,
                    exec_path=exec_path))
                continue

        # dpkg-owned application (Kali menu wale normal tools)
        owner = owners.get(fp)
        if not owner and exec_path:
            owner = owners.get(exec_path)
        if not owner and exec_path and per_query < 400 \
                and time.monotonic() < pq_dl:
            owner = _owner_of_path(exec_path)       # extended fallback queries
            per_query += 1
        if owner and owner in pkg_map:
            p = pkg_map[owner]
            items.append(Item(
                iid="app::" + stem, kind="app", strategy="apt",
                display=display, name=owner, version=p.version, kb=p.kb,
                section=p.section or "application",
                summary=p.summary or comment or "Installed application",
                owner=owner, icon_key=icon_key, desktop_path=fp,
                exec_path=exec_path))
        else:
            # GitHub / custom tool — dpkg iska owner nahi hai
            summary = comment or "Custom / GitHub tool"
            items.append(Item(
                iid="app::" + stem, kind="app", strategy="files",
                display=display, name=stem, version="custom",
                section="github/custom",
                summary=summary + "  •  launcher + program files delete honge",
                owner=None, icon_key=icon_key, desktop_path=fp,
                exec_path=exec_path))

    # ---------- phase 5: pure apt packages -----------------------------------
    # (jo package kisi app item se pehle se cover ho — owner match — to
    #  dobara plain row nahi banayi jati; list saaf rehti hai)
    covered = {it.owner for it in items if it.strategy == "apt" and it.owner}
    for p in pkg_map.values():
        if p.name in covered:
            continue
        items.append(Item(
            iid=p.name, kind="apt", strategy="apt", display=p.name,
            name=p.name, version=p.version, kb=p.kb, section=p.section,
            summary=p.summary))

    items.sort(key=lambda it: it.display.lower())
    return items, owners


def build_all_items(pkg_map):
    """COMPAT: poora list ek call me (streaming ke bina) — tests/scripts.

    GUI asal me _load_worker se build_core_items + build_extra_stream
    use karta hai (instant paint + parallel sources).
    """
    items, owners = build_core_items(pkg_map)
    taken_names = {(it.display or "").lower() for it in items}
    taken_names |= {it.name.lower() for it in items if it.strategy == "apt"}
    taken_execs = {it.exec_path for it in items if it.exec_path}
    items.extend(build_extra_items(pkg_map, taken_names, taken_execs, []))
    items.sort(key=lambda it: it.display.lower())
    return items, owners


