def _deep_tokens(name):
    """Tool name ke search tokens banao (package/display name se)."""
    n = (name or "").strip().lower()
    if not n:
        return []
    n = re.sub(r"[^a-z0-9+._\- ]", " ", n).strip()
    toks = []
    if len(n) >= 4:
        toks.append(n)                       # poora naam pehle
    for p in re.split(r"[-_.\s]+", n):
        if len(p) >= 4 and p not in _DEEP_TOKEN_SKIP and p not in toks:
            toks.append(p)
    return toks[:8]


def _deep_match(basename, toks):
    """basename kisi token se match? -> matched token ya None."""
    b = basename.lower()
    for v in (b, b.replace("_", "-"), b.replace("-", "_")):
        for t in toks:
            if t == v or (len(t) >= 4 and t in v):
                return t
    return None


def _deep_size_kb(path, file_cap=250, budget=0.6):
    """File/dir ka size KB me — ESTIMATE (cap + time budget ke saath — fast).

    HDD par 8000-file walk per match = minute lagte the (5-min hang ka
    ek wajah). Ab max 250 files / 0.6s — kaafi sahi estimate display ke
    liye, aur kabhi slow nahi.
    """
    t0 = time.monotonic()
    try:
        if os.path.islink(path):
            return 1
        if os.path.isfile(path):
            return max(1, os.path.getsize(path) // 1024)
        total, n = 0, 0
        for r, _ds, fs in os.walk(path):
            for f in fs:
                n += 1
                if n > file_cap or (time.monotonic() - t0) > budget:
                    return max(1, total // 1024 + 1)
                try:
                    total += os.path.getsize(os.path.join(r, f))
                except OSError:
                    pass
        return total // 1024
    except OSError:
        return 0


def deep_scan_leftovers(names, include_orphans=True, progress=None,
                        should_stop=None, on_found=None, deadline=60.0,
                        root_budget=5.0, nthreads=6):
    """❄ DEEP SCAN engine v4.1 — FAST edition (parallel + budget + streaming).

    names           : tool/package/display names ki list
    include_orphans : Exec-binary-missing .desktop launchers bhi dhoondo
    progress        : fn(text) — status updates
    should_stop     : fn() -> bool — scan rokne ke liye
    on_found        : fn(match_dict) — LIVE streaming; jaise hi koi leftover
                      dpkg-filter pass karta hai ye fire hota hai (GUI me
                      rows scan ke dauran hi aati hain, end ka intezaar
                      nahi)
    deadline        : global wall-clock limit (sec) — scan HAMESHA khatam
    root_budget     : har root ka apna time budget (sec)
    nthreads        : parallel root scan threads
    Returns dict:
      tokens, matches [{path, kb, kind, token}], owned_skipped, stopped
    """
    def say(t):
        if progress:
            try:
                progress(t)
            except Exception:
                pass

    t0 = time.monotonic()
    dl = t0 + deadline                      # global deadline

    def stopped():
        try:
            if bool(should_stop()):
                return True
        except Exception:
            pass
        return time.monotonic() > dl        # deadline bhi stop hai

    def elapsed():
        return time.monotonic() - t0

    toks = []
    for n in names:
        for t in _deep_tokens(n):
            if t not in toks:
                toks.append(t)
    out = {"tokens": toks, "matches": [], "owned_skipped": 0,
           "stopped": False}
    if not toks:
        return out
    say("tokens: " + ", ".join(toks))
    home = _real_home()
    candidates = []                       # (path, kind, token)
    seen = set()
    lock = threading.Lock()

    def add_cand(full, kind, tok):
        real = os.path.realpath(full)
        with lock:
            if real in seen:
                return
            seen.add(real)
            candidates.append((full, kind, tok))

    # ------------------------------------------------ walk ek root ka ----
    roots_total = len(DEEP_SCAN_ROOTS)
    roots_done = {"n": 0}

    def _walk_root(root, depth, kind):
        rp = root.replace("~", home, 1) if root.startswith("~") else root
        try:
            if not os.path.isdir(rp):
                return
            say(f"[{elapsed():4.1f}s] scanning: {rp}")
            rs = time.monotonic()
            if kind == "HOME-DOTDIR":
                try:
                    entries = sorted(os.listdir(rp))
                except OSError:
                    return
                for d in entries:
                    if stopped():
                        break
                    if not d.startswith(".") or d in (
                            ".config", ".cache", ".local", ".gnupg", ".ssh",
                            ".pki", ".dbus", ".java", ".fontconfig", ".icons",
                            ".themes"):
                        continue
                    if d in _DEEP_SKIP:
                        continue
                    full = os.path.join(rp, d)
                    tok = _deep_match(d, toks)
                    if tok and not os.path.islink(full):
                        add_cand(full, kind, tok)
                return
            base_depth = rp.rstrip("/").count("/")
            try:
                walker = os.walk(rp, topdown=True, followlinks=False)
            except OSError:
                return
            for cur, dirs, fs in walker:
                if stopped():
                    dirs[:] = []
                    return
                if time.monotonic() - rs > root_budget:
                    say(f"[{elapsed():4.1f}s] budget khatam — skip deeper: "
                        f"{rp}")
                    dirs[:] = []
                    return
                if cur.rstrip("/").count("/") - base_depth >= depth:
                    dirs[:] = []
                keep = []
                for d in sorted(dirs):
                    if d.startswith(".") or d in _DEEP_SKIP:
                        continue
                    full = os.path.join(cur, d)
                    if os.path.islink(full):
                        keep.append(d)            # symlink follow na karo
                        continue
                    tok = _deep_match(d, toks)
                    if tok:
                        add_cand(full, kind, tok)
                    else:
                        keep.append(d)            # match nahi -> andar jao
                dirs[:] = keep
                if kind in ("BINARY", "LOG"):
                    for f in fs:
                        if f.startswith(".") or f in _DEEP_SKIP:
                            continue
                        tok = _deep_match(f, toks)
                        if tok:
                            add_cand(os.path.join(cur, f), kind, tok)
        except Exception:
            pass
        finally:
            with lock:
                roots_done["n"] += 1
                say(f"[{elapsed():4.1f}s] roots {roots_done['n']}/"
                    f"{roots_total} done")

    # ---- PARALLEL root scan (6 threads) — HDD par bhi fast ----
    try:
        with ThreadPoolExecutor(max_workers=max(2, nthreads)) as pool:
            futs = [pool.submit(_walk_root, r, d, k)
                    for r, d, k in DEEP_SCAN_ROOTS]
            for f in as_completed(futs):
                try:
                    f.result()
                except Exception:
                    pass
    except Exception:
        pass                                  # fallback: jitne mile wo kaafi
    if stopped():
        out["stopped"] = True

    # ---- orphaned launchers (Exec ka binary mojood nahi) ----
    if include_orphans and not stopped():
        say(f"[{elapsed():4.1f}s] scanning: orphaned .desktop launchers...")
        lpaths = []
        for sd in desktop_source_dirs():
            try:
                for fn in sorted(os.listdir(sd)):
                    if fn.endswith(".desktop"):
                        lpaths.append(os.path.join(sd, fn))
            except OSError:
                continue
        owned_l = _bulk_owners(lpaths)
        for fp in lpaths:
            if stopped():
                out["stopped"] = True
                break
            if fp in owned_l:
                continue
            ent = parse_desktop(fp)
            if not ent:
                continue
            ev = (ent.get("exec") or "").strip()
            if not ev or _resolve_exec(ev):
                continue                       # binary zinda hai
            stem = os.path.basename(fp)[:-len(".desktop")]
            add_cand(fp, "ORPHAN LAUNCHER", stem)

    # ---- dpkg-owned filter (bulk, PARALLEL chunks) + LIVE streaming ----
    if candidates:
        say(f"[{elapsed():4.1f}s] dpkg ownership check: "
            f"{len(candidates)} paths...")
        CH = 90
        chunks = [(i, candidates[i:i + CH])
                  for i in range(0, len(candidates), CH)]

        def _emit(cpart, owned_map):
            real_owned = {os.path.realpath(p) for p in owned_map}
            for path, kind, tok in cpart:
                rp = os.path.realpath(path)
                if path in owned_map or rp in real_owned:
                    out["owned_skipped"] += 1
                    continue
                m = {"path": path, "kb": _deep_size_kb(path),
                     "kind": kind, "token": tok}
                out["matches"].append(m)
                if on_found:
                    try:
                        on_found(dict(m))      # LIVE row GUI me
                    except Exception:
                        pass

        with ThreadPoolExecutor(max_workers=4) as pool:
            futs = {}
            for idx, cpart in chunks:
                if stopped():
                    break
                futs[pool.submit(_bulk_owners,
                                 [c[0] for c in cpart])] = cpart
            for fut in as_completed(futs):
                cpart = futs[fut]
                try:
                    _emit(cpart, fut.result() or {})
                except Exception:
                    pass
                if stopped():
                    for ff in futs:
                        ff.cancel()
                    break
        if stopped():
            out["stopped"] = True
    out["matches"].sort(key=lambda m: (-m["kb"], m["path"]))
    say(f"[{elapsed():4.1f}s] deep scan done: {len(out['matches'])} "
        f"leftovers, {out['owned_skipped']} dpkg-owned skip ho gaye")
    return out


def deep_delete_paths(paths, log=None):
    """Deep scan results delete karo — LIVE dpkg check + protected guards.

    Returns (ok, skipped_failed, freed_kb).
    """
    say = log or (lambda t: None)
    home = os.path.realpath(_real_home())
    protect = {
        "/", "/usr", "/usr/local", "/usr/share", "/usr/local/bin",
        "/usr/local/share", "/usr/local/lib", "/etc", "/etc/apt",
        "/var", "/var/lib", "/var/cache", "/var/log", "/var/tmp", "/tmp",
        "/opt", "/boot", "/snap", "/srv", "/root",
        home, home + "/.config", home + "/.cache", home + "/.local",
        home + "/.local/share", home + "/.local/share/applications",
        home + "/.local/bin", home + "/.local/state", home + "/Desktop",
        "/usr/share/applications",
    }
    ok = bad = freed_kb = 0
    for p in paths:
        rp = os.path.normpath(p)
        try:
            real = os.path.realpath(rp)
        except OSError:
            real = rp
        comps = [c for c in rp.split("/") if c]
        why = None
        if real in protect or rp in protect:
            why = "protected path"
        elif len(comps) < 2:
            why = "bohat top-level path"
        elif _owner_of_path(rp) or _owner_of_path(real):
            why = "dpkg package ki file"
        if why:
            say(f"[skip] {rp} — {why}")
            bad += 1
            continue
        try:
            if os.path.islink(rp) or os.path.isfile(rp):
                try:
                    freed_kb += os.path.getsize(real) // 1024
                except OSError:
                    pass
                os.remove(rp)
            elif os.path.isdir(rp):
                inner, n = [], 0
                for r, _ds, fs in os.walk(rp):
                    for f in fs:
                        n += 1
                        if n > 800:
                            break
                        inner.append(os.path.join(r, f))
                    if n > 800:
                        break
                if inner:
                    owners = sorted({v for v in
                                     _bulk_owners(inner).values()})
                    if owners:
                        say(f"[skip] {rp} — andar dpkg files hain: "
                            f"{', '.join(owners[:3])}")
                        bad += 1
                        continue
                for r, _ds, fs in os.walk(rp):
                    for f in fs:
                        try:
                            freed_kb += os.path.getsize(
                                os.path.join(r, f)) // 1024
                        except OSError:
                            pass
                shutil.rmtree(rp)
            else:
                say(f"[skip] {rp} — mojood nahi")
                bad += 1
                continue
            ok += 1
            say(f"[deleted] {rp}")
        except Exception as exc:
            say(f"[error] {rp}: {exc}")
            bad += 1
    say(f"deep clean finished: {ok} delete, {bad} skip/fail")
    return ok, bad, freed_kb


# ------------------------------------------------------ SVG -> PNG --------
def _svg_png(svg_path, target):
    """SVG icon ko PNG me convert karo (jo converter mile), cache ke saath."""
    try:
        os.makedirs(ICON_CACHE, exist_ok=True)
    except OSError:
        return None
    try:
        stamp = int(os.path.getmtime(svg_path))
    except OSError:
        stamp = 0
    out = os.path.join(
        ICON_CACHE,
        f"{os.path.basename(svg_path)}.{stamp}.{target}.png")
    if os.path.isfile(out) and os.path.getsize(out) > 0:
        return out
    px = max(target * 2, 64)
    for argv in (
        ["rsvg-convert", "-w", str(px), "-h", str(px), "-o", out, svg_path],
        ["convert", "-background", "none", svg_path,
         "-resize", f"{px}x{px}", out],
        ["inkscape", svg_path, "--export-type=png",
         "--export-filename=" + out, "-w", str(px)],
    ):
        if shutil.which(argv[0]) is None:
            continue
        try:
            res = subprocess.run(argv, capture_output=True, timeout=30)
            if res.returncode == 0 and os.path.isfile(out) \
                    and os.path.getsize(out) > 0:
                return out
        except Exception:
            continue
    return None


def _icon_photo(path, target):
    """Icon path -> PhotoImage. SVG pehle convert hota hai."""
    if not path:
        return None
    if path.lower().endswith(".svg"):
        path = _svg_png(path, target)
        if not path:
            return None
    return _fit_photo(path, target)


class IconIndex:
    """System .desktop entries + icon theme index -> REAL tool icons.

    Kali par har tool ka apna icon hota hai (hicolor theme, pixmaps, ya
    .desktop file ke Icon= field me). Ye class ek dafa sab scan karke
    package-name -> icon-file map banati hai. Sirf filesystem scan —
    koi extra dependency nahi.
    """

    def __init__(self):
        self.ready = False
        self.pools = {}        # icon-name -> best png/gif/svg path
        self.by_stem = {}      # desktop-file stem -> Icon value
        self.by_exec = {}      # Exec binary name -> Icon value
        self.by_name = {}      # Name= value -> Icon value
        self._sorted = None

    # ------------------------------------------------------ scanning ---
    def build(self):
        try:
            self._scan_themes()
        except Exception:
            pass
        try:
            self._scan_desktops()
        except Exception:
            pass
        self.ready = True

    def _scan_themes(self):
        import glob
        best = {}
        size_order = {"48x48": 0, "64x64": 1, "32x32": 2, "96x96": 3,
                      "72x72": 4, "128x128": 5, "36x36": 6, "24x24": 7,
                      "16x16": 8, "256x256": 9, "512x512": 10,
                      "scalable": 12}
        theme_roots = ["/usr/share/icons", "/usr/local/share/icons",
                       "/var/lib/flatpak/exports/share/icons"]
        for root in theme_roots:
            theme_dirs = glob.glob(root + "/*")
            theme_dirs.sort(key=lambda p: (0 if p.endswith("/hicolor") else 1,
                                           p))
            for td in theme_dirs:
                for sd in glob.glob(td + "/*/apps"):
                    sz = os.path.basename(os.path.dirname(sd))
                    pref = size_order.get(sz, 50)
                    for fp in (glob.glob(sd + "/*.png")
                               + glob.glob(sd + "/*.gif")
                               + glob.glob(sd + "/*.svg")):
                        name = os.path.splitext(os.path.basename(fp))[0].lower()
                        old = best.get(name)
                        if old is None or pref < old[0]:
                            best[name] = (pref, fp)
        # classic pixmaps directory (bohat se tools yahan icons rakhte hain)
        for root in ("/usr/share/pixmaps", "/usr/local/share/pixmaps"):
            for fp in (glob.glob(root + "/*.png") + glob.glob(root + "/*.gif")
                       + glob.glob(root + "/*.svg")):
                name = os.path.splitext(os.path.basename(fp))[0].lower()
                old = best.get(name)
                if old is None or 25 < old[0]:
                    best[name] = (25, fp)
        self.pools = {k: v[1] for k, v in best.items()}

    def _scan_desktops(self):
        import glob
        files = []
        for d in desktop_source_dirs():
            files += glob.glob(d + "/*.desktop")
            files += glob.glob(d + "/*/*.desktop")
        for fp in files:
            try:
                icon = exec_ = name = None
                in_entry = False
                with open(fp, "r", encoding="utf-8", errors="ignore") as fh:
                    for line in fh:
                        line = line.strip()
                        if line.startswith("["):
                            in_entry = line.lower() == "[desktop entry]"
                            continue
                        if not in_entry or "=" not in line:
                            continue
                        k, _, v = line.partition("=")
                        k = k.strip().lower()
                        v = v.strip()
                        if k == "icon" and not icon:
                            icon = v
                        elif k == "exec" and not exec_:
                            exec_ = v
                        elif k == "name" and not name:
                            name = v
                        if icon and exec_ and name:
                            break
            except OSError:
                continue
            if not icon:
                continue
            stem = os.path.splitext(os.path.basename(fp))[0].lower()
            self._put(self.by_stem, stem, icon)
            if exec_:
                exe = exec_.split()[0].strip('"').strip("'")
                exe = os.path.basename(exe).lower()
                if exe:
                    self._put(self.by_exec, exe, icon)
            if name:
                self._put(self.by_name, name.lower(), icon)

    @staticmethod
    def _put(d, k, v):
        if k and k not in d:
            d[k] = v

    # ----------------------------------------------------- resolution ---
    def resolve_icon_key(self, key):
        """Icon= value (path ya theme name) -> actual icon file path."""
        if not key:
            return None
        if key.startswith("/"):
            base = os.path.splitext(key)[0]
            for ext in (".png", ".gif", ".svg"):
                if os.path.isfile(base + ext):
                    return base + ext
            low = key.lower()
            if low.endswith((".png", ".gif", ".svg")) and os.path.isfile(key):
                return key
            return None
        return self.pools.get(key.lower())

    # purana naam bhi kaam kare (compatibility)
    _resolve_key = resolve_icon_key

    def _shortest_prefixed(self, d, prefix):
        """Map me sab se chhota key jo `prefix` se start hota hai."""
        if self._sorted is None:
            self._sorted = {name: sorted(m) for name, m in
                            (("stem", self.by_stem), ("exec", self.by_exec),
                             ("name", self.by_name))}
        keys = self._sorted[d]
        i = bisect.bisect_left(keys, prefix)
        if i < len(keys) and keys[i].startswith(prefix):
            return keys[i]
        return None

    def find(self, pkg):
        """Package name -> real icon file path, ya None (fallback glyph)."""
        p = pkg.lower()
        # 1) exact matches (sab se sahi)
        for val in (self.by_stem.get(p), self.by_exec.get(p),
                    self.by_name.get(p), self.pools.get(p)):
            path = self.resolve_icon_key(val)
            if path:
                return path
        # 2) kali- prefixed desktop entries (Kali tools ka common pattern)
        for dname, d in (("stem", self.by_stem), ("exec", self.by_exec),
                         ("name", self.by_name)):
            k = self._shortest_prefixed(dname, "kali-" + p)
            if k:
                path = self.resolve_icon_key(d[k])
                if path:
                    return path
        # 3) suffix variants (burpsuite -> burpsuite-community, waghera)
        for dname, d in (("stem", self.by_stem), ("exec", self.by_exec),
                         ("name", self.by_name)):
            k = self._shortest_prefixed(dname, p + "-")
            if k:
                path = self.resolve_icon_key(d[k])
                if path:
                    return path
        return None


def _fit_photo(path, target):
    """Icon file -> PhotoImage, target size se fit (subsample)."""
    try:
        ph = tk.PhotoImage(file=path)
    except Exception:
        return None
    s = max(ph.width(), ph.height())
    if s > target + 2:
        f = max(1, -(-s // target))                   # ceil division
        try:
            ph = ph.subsample(f, f)
        except tk.TclError:
            pass
    return ph


# --------------------------------------------------------------- splash ---
class Splash(tk.Toplevel):
    """Full splash card: snow wallpaper, frost frame, exact 4 second timer."""

    def __init__(self, master):
        super().__init__(master)
        self.overrideredirect(True)
        self.configure(bg=VIOLET)
        self.attributes("-topmost", True)

        sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        self.photo = None
        rw = rh = None

        inner = tk.Frame(self, bg=BG, padx=3, pady=3)
        inner.pack(fill="both", expand=True)

        base = _tk_png(EMBED_SPLASH_B64)
        if base is not None:
            self._splash_base = base                     # reference rakho
            iw, ih = base.width(), base.height()
            factor = 1
            while (iw // factor > sw - 100 or ih // factor > sh - 180) \
                    and factor < 8:
                factor += 1
            self.photo = base if factor == 1 else base.subsample(factor, factor)
            w, h = self.photo.width(), self.photo.height()
            tk.Label(inner, image=self.photo, bg=BG, borderwidth=0).pack()
            tk.Frame(inner, bg=RED, height=2).pack(fill="x")
            bar = tk.Frame(inner, bg=PANEL2, height=58)
            bar.pack(fill="both", expand=True)
            bar.pack_propagate(False)
            tk.Label(bar, text="KALI UNINSTALLER", bg=PANEL2, fg=TXT,
                     font=("DejaVu Sans", 14, "bold")).pack(side="left", padx=14)
            tk.Label(bar, text="v" + APP_VER + "  •  WHITEOUT EDITION",
                     bg=PANEL2, fg=PURPLE,
                     font=("DejaVu Sans", 9, "bold")).pack(side="left")
            right = tk.Frame(bar, bg=PANEL2)
            right.pack(side="right", padx=14)
            tk.Label(right, text="LOADING ROOT ACCESS...", bg=PANEL2, fg=RED,
                     font=("DejaVu Sans", 10, "bold")).pack(anchor="e")
            self.pbar = ttk.Progressbar(right, mode="indeterminate", length=210,
                                        style="fox.Horizontal.TProgressbar")
            self.pbar.pack(anchor="e", pady=(5, 0))
            self.pbar.start(14)
            # exact window size: image + 6px inner padding + 6px neon border
            rw, rh = w + 12, h + 6 + 6 + 2 + 58
        else:
            # fallback (embedded image decode na ho to)
            rw, rh = 740, 250
            tk.Label(inner, text="KALI UNINSTALLER", bg=BG, fg=RED,
                     font=("DejaVu Sans", 26, "bold"), pady=46).pack()
            tk.Label(inner, text="LOADING ROOT ACCESS...", bg=BG, fg=PURPLE,
                     font=("DejaVu Sans", 11, "bold")).pack(pady=8)

        x, y = max((sw - rw) // 2, 0), max((sh - rh) // 2, 0)
        self.geometry(f"{rw}x{rh}+{x}+{y}")
        self.lift()

# ------------------------------------------------------- confirm dialog ---
class Confirm(tk.Toplevel):
    """Danger confirmation before uninstalling. result=True on YES.

    groups: list of (title, subline, [names]) — har removal strategy ka
    apna panel (APT purge / GITHUB-CUSTOM files / FLATPAK / SNAP).
    """

    GROUP_COLORS = {
        "APT PURGE":               RED_DIM,
        "GITHUB / CUSTOM TOOL REMOVE": VIOLET,
        "FLATPAK UNINSTALL":       BLUE,
        "SNAP REMOVE":             BLUE,
    }

    def __init__(self, parent, groups, warn_icon=None, total_kb=0,
                 crit_names=(), heading="CONFIRM UNINSTALL",
                 yes_text="YES, REMOVE", show_full_remove=True):
        super().__init__(parent)
        self.result = False
        self.full_remove = True               # default: FULL REMOVE ON
        self.configure(bg=BG)
        self.title("Confirm")
        self.transient(parent)
        self.resizable(False, False)
        self.attributes("-topmost", True)

        n_total = sum(len(names) for _, _, names in groups)

        head = tk.Frame(self, bg=BG)
        head.pack(fill="x", padx=26, pady=(22, 4))
        if warn_icon is not None:
            tk.Label(head, image=warn_icon, bg=BG).pack(
                side="left", padx=(0, 14))
        tk.Frame(head, bg=RED, width=7).pack(side="left", fill="y", padx=(0, 14))
        box = tk.Frame(head, bg=BG)
        box.pack(side="left")
        tk.Label(box, text=heading, bg=BG, fg=TXT,
                 font=("DejaVu Sans", 16, "bold")).pack(anchor="w")
        sub = f"{n_total} item{'s' if n_total > 1 else ''}"
        if total_kb:
            sub += f"  •  apt size {fmt_size(total_kb)}"
        tk.Label(box, text=sub, bg=BG, fg=PURPLE,
                 font=("DejaVu Sans", 10, "bold")).pack(anchor="w")
        tk.Label(box, text="Ye operation ULTA nahi ho sakta!", bg=BG, fg=DIM,
                 font=("DejaVu Sans", 9)).pack(anchor="w")

        # har strategy ka apna panel
        for title, subline, names in groups:
            color = self.GROUP_COLORS.get(title, PURPLE)
            gf = tk.Frame(self, bg=PANEL, highlightthickness=1,
                          highlightbackground=BORDER)
            gf.pack(fill="x", padx=26, pady=6)
            tk.Label(gf, text=f"▸ {title}  ({len(names)})",
                     bg=PANEL, fg=color,
                     font=("DejaVu Sans", 10, "bold")).pack(
                anchor="w", padx=14, pady=(8, 2))
            shown = ", ".join(names[:8]) + ("..." if len(names) > 8 else "")
            tk.Label(gf, text=shown, bg=PANEL, fg=TXT, justify="left",
                     font=("DejaVu Sans Mono", 10), wraplength=460,
                     padx=14).pack(anchor="w")
            tk.Label(gf, text=subline, bg=PANEL, fg=DIM,
                     font=("DejaVu Sans Mono", 8), wraplength=460,
                     justify="left").pack(anchor="w", padx=14, pady=(2, 8))

        if crit_names:
            tk.Label(self, text="!! CRITICAL SYSTEM PACKAGE — ye remove karne se "
                                "system break ho sakta hai: "
                                + ", ".join(crit_names[:6]),
                     bg=BG, fg=RED, font=("DejaVu Sans", 10, "bold"),
                     wraplength=470, justify="left").pack(padx=26, pady=(4, 6),
                                                          anchor="w")

        # ---- FULL REMOVE checkbox (Revo-style auto leftover clean) ----
        if show_full_remove:
            ff = tk.Frame(self, bg=PANEL, highlightthickness=1,
                          highlightbackground=BORDER)
            ff.pack(fill="x", padx=26, pady=(2, 6))
            self.full_var = tk.BooleanVar(value=True)
            tk.Checkbutton(ff, text=("FULL REMOVE — uninstall ke baad bachay "
                                     "hue leftovers (configs, caches, "
                                     "launchers) bhi AUTO-DELETE honge "
                                     "(dpkg-owned files safe rehti hain)"),
                           variable=self.full_var, bg=PANEL, fg=VIOLET,
                           activebackground=PANEL, activeforeground=TXT,
                           selectcolor=BG, font=("DejaVu Sans", 9, "bold"),
                           bd=0, highlightthickness=0, cursor="hand2",
                           wraplength=430, justify="left").pack(
                anchor="w", padx=12, pady=8)

        btns = tk.Frame(self, bg=BG)
        btns.pack(fill="x", padx=26, pady=18)
        yes = tk.Button(btns, text=yes_text, command=self._yes,
                        bg=RED, fg="white", activebackground="#d92042",
                        activeforeground="white", relief="flat", bd=0,
                        font=("DejaVu Sans", 12, "bold"), padx=22, pady=9,
                        cursor="hand2")
        yes.pack(side="right")
        no = tk.Button(btns, text="CANCEL", command=self.destroy,
                       bg=PANEL2, fg=TXT, activebackground=BORDER,
                       activeforeground=TXT, relief="flat", bd=0,
                       font=("DejaVu Sans", 11, "bold"), padx=22, pady=9,
                       cursor="hand2")
        no.pack(side="right", padx=(0, 12))
        yes.bind("<Enter>", lambda e: yes.configure(bg=RED_HOT))
        yes.bind("<Leave>", lambda e: yes.configure(bg=RED))

        self.update_idletasks()
        px, py = parent.winfo_rootx(), parent.winfo_rooty()
        pw, ph = parent.winfo_width(), parent.winfo_height()
        self.geometry(f"+{px + (pw - self.winfo_reqwidth()) // 2}"
                      f"+{py + (ph - self.winfo_reqheight()) // 2}")
        self.grab_set()
        no.focus_set()
        self.bind("<Return>", lambda e: self.destroy())
        self.bind("<Escape>", lambda e: self.destroy())

    def _yes(self):
        self.result = True
        try:
            self.full_remove = bool(self.full_var.get())
        except Exception:
            self.full_remove = True
        self.destroy()


